-- ALTER TABLE subcommand lists combine relation-level subcommands with column
-- and constraint ones; SET and RESET reach view options through ALTER TABLE.
create table t212 (id int primary key, a int); create index t212_a on t212 (a);
create table parent212 (id int);
create type ct212 as (id int, a int, b int);
create function tf212() returns trigger language plpgsql as $$ begin return new; end $$;
create trigger tr212 before insert on t212 for each row execute function tf212();
alter table t212 disable trigger tr212, add column b int, set logged;
select tgenabled from pg_trigger where tgname = 'tr212';
alter table t212 enable always trigger tr212, cluster on t212_a, replica identity full,
  enable row level security, force row level security;
select tgenabled from pg_trigger where tgname = 'tr212';
select relreplident, relrowsecurity, relforcerowsecurity from pg_class where relname = 't212';
select indisclustered from pg_index where indexrelid = 't212_a'::regclass;
alter table t212 set without cluster, no force row level security,
  disable row level security, replica identity default;
select relreplident, relrowsecurity, relforcerowsecurity from pg_class where relname = 't212';
alter table t212 enable trigger nosuch, add column q int;
create table c212 (id int, a int, b int);
alter table c212 inherit parent212, alter column a set not null;
select inhparent::regclass from pg_inherits where inhrelid = 'c212'::regclass;
alter table c212 no inherit parent212, of ct212;
select reloftype::regtype from pg_class where relname = 'c212';
alter table c212 not of, add column z int;
alter table c212 add column y int, set schema public;
alter table c212 add column y int, rename to d212;
alter table c212 set schema public, add column y int;
alter table c212 alter column a drop not null, alter column b set not null;
alter table c212 rename column a to aa;
alter table c212 drop column b;
alter table c212 alter column a type bigint;
create table d212 (id int, x int);
alter table d212 of ct212;
create table e212 (id int, a bigint, b int);
alter table e212 of ct212;
create table f212 (id int, a int);
alter table f212 of ct212;
create table g212 (id int, a int, b int, z int);
alter table g212 of ct212;
create view v212 as select * from t212;
create materialized view m212 as select * from t212;
alter table v212 set (security_barrier = true);
select reloptions from pg_class where relname = 'v212';
alter table v212 set (security_barrier = false, check_option = local);
select reloptions from pg_class where relname = 'v212';
alter table v212 reset (security_barrier);
select reloptions from pg_class where relname = 'v212';
alter table v212 set (fillfactor = 50);
alter table v212 set (security_barrier = true, fillfactor = 50);
alter table v212 reset (fillfactor, nosuch);
alter table t212 set (security_barrier = true);
alter table t212 set (fillfactor = 50, security_barrier = true);
alter table t212 reset (security_barrier, nosuch);
alter table t212 set (check_option = local);
alter table v212 set (check_option = bad);
alter materialized view m212 set (security_barrier = true);
alter materialized view m212 reset (security_barrier);
alter view v212 set (nosuch = 1);
alter view v212 reset (check_option), set (security_barrier = true), alter column id set default 1;
select reloptions from pg_class where relname = 'v212';
alter view v212 reset (security_barrier), set (security_invoker = true);
select reloptions from pg_class where relname = 'v212';
drop view v212;
drop materialized view m212;
drop table t212, c212, parent212, d212, e212, f212, g212;
drop type ct212;
drop function tf212();
